package org.mockito.internal.util.reflection;

import java.io.*;
import java.lang.reflect.Field;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class GenericMaster_getGenericType_TriageGen1Test {

    private GenericMaster genericMaster;

    @Before
    public void setUp() {
        genericMaster = new GenericMaster();
    }

    @Test
    public void testGetGenericType_NullGeneric() throws NoSuchFieldException {
        Field field = mock(Field.class);
        when(field.getGenericType()).thenReturn(null);

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(Object.class, result);
    }

    @Test
    public void testGetGenericType_NotParameterizedType() throws NoSuchFieldException {
        Field field = mock(Field.class);
        when(field.getGenericType()).thenReturn(String.class);

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(Object.class, result);
    }

    @Test
    public void testGetGenericType_ParameterizedTypeWithClassAsSecondArgument() throws NoSuchFieldException {
        Field field = mock(Field.class);
        ParameterizedType parameterizedType = mock(ParameterizedType.class);

        // Mocking: Map<String, Integer> -> index 1 is Integer.class
        when(field.getGenericType()).thenReturn(parameterizedType);
        when(parameterizedType.getActualTypeArguments()).thenReturn(new Type[]{String.class, Integer.class});

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(Integer.class, result);
    }

    @Test
    public void testGetGenericType_ParameterizedTypeWithNestedParameterizedType() throws NoSuchFieldException {
        Field field = mock(Field.class);
        ParameterizedType outerType = mock(ParameterizedType.class);
        ParameterizedType innerType = mock(ParameterizedType.class);

        // Mocking: Map<String, List<String>> -> index 1 is List<String>
        // List<String> is a ParameterizedType, we expect the raw type: List.class
        when(field.getGenericType()).thenReturn(outerType);
        when(outerType.getActualTypeArguments()).thenReturn(new Type[]{String.class, innerType});
        when(innerType.getRawType()).thenReturn(java.util.List.class);

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(java.util.List.class, result);
    }

    @Test
    public void testGetGenericType_ParameterizedTypeWithNonClassNonParameterizedType() throws NoSuchFieldException {
        Field field = mock(Field.class);
        ParameterizedType parameterizedType = mock(ParameterizedType.class);
        Type nonClassType = mock(Type.class); // Not Class and not ParameterizedType

        when(field.getGenericType()).thenReturn(parameterizedType);
        when(parameterizedType.getActualTypeArguments()).thenReturn(new Type[]{String.class, nonClassType});

        Class<?> result = genericMaster.getGenericType(field);

        assertEquals(Object.class, result);
    }
}
